}
"use server";

import { redirect } from "next/navigation";

import { preferenciasSchema } from "@/features/preferencias/schema";
import { createClient } from "@/lib/supabase/server";

export type EstadoPreferencias = { mensagem?: string };

const ERRO_GENERICO = "Não foi possível salvar agora. Tente de novo.";

export async function salvarPreferencias(
  _anterior: EstadoPreferencias,
  formData: FormData,
): Promise<EstadoPreferencias> {
  const resultado = preferenciasSchema.safeParse({
    generos: formData.getAll("generos").map(Number),
    duracao: formData.get("duracao"),
    frequencia: formData.get("frequencia"),
  });
  if (!resultado.success) {
    return { mensagem: resultado.error.issues[0]?.message ?? ERRO_GENERICO };
  }

  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) redirect("/login?next=%2Fonboarding");

  const { error } = await supabase
    .from("preferencias")
    .upsert({ usuario_id: user.id, ...resultado.data });
  if (error) {
    console.error("[preferencias] falha ao salvar:", error.code, error.message);
    return { mensagem: ERRO_GENERICO };
  }

  redirect("/dashboard");
}
import "server-only";

import { GENEROS } from "@/features/preferencias/generos";
import { motivoParecido, motivoPorGeneros, tituloParecidos } from "@/features/recomendacao/motivo";
import { agregarParecidos } from "@/features/recomendacao/parecidos";
import { planejar, type Consulta } from "@/features/recomendacao/planejar";
import { bonusPorGenero, pontuar } from "@/features/recomendacao/ranquear";
import { criarGerador } from "@/features/recomendacao/semente";
import type { EntradaMotor, Recomendacao, Secao } from "@/features/recomendacao/tipos";
import { descobrirFilmes, recomendacoesDe, type ApiFilmes } from "@/lib/tmdb/filmes";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

export type ApiMotor = Pick<ApiFilmes, "descobrirFilmes" | "recomendacoesDe">;

const API_PADRAO: ApiMotor = { descobrirFilmes, recomendacoesDe };
const MAX_POR_SECAO = 20;

type Resultado = { consulta: Consulta; filmes: FilmeResumo[] | null };

async function executar(consulta: Consulta, api: ApiMotor): Promise<Resultado> {
  try {
    const pagina =
      consulta.tipo === "parecidos"
        ? await api.recomendacoesDe(consulta.origem.tmdbId)
        : await api.descobrirFilmes(consulta.filtros);
    return { consulta, filmes: pagina.itens };
  } catch (erro) {
    console.error(`[recomendacao] consulta ${consulta.tipo} falhou:`, erro);
    return { consulta, filmes: null };
  }
}

function semRepetidos(filmes: FilmeResumo[]): FilmeResumo[] {
  return [...new Map(filmes.map((filme) => [filme.id, filme])).values()];
}

/**
 * Monta as seções de recomendação: "Escolhidos para você", os parecidos com filmes
 * bem avaliados e uma por gênero favorito. Cada filme aparece numa única seção.
 */
export async function gerarRecomendacoes(
  entrada: EntradaMotor,
  api: ApiMotor = API_PADRAO,
): Promise<Secao[]> {
  const { preferencias, reacoes = [] } = entrada;
  const gerador = criarGerador(entrada.usuarioId, entrada.data, entrada.rodada ?? 0);
  const plano = planejar(entrada, gerador);
  const resultados = await Promise.all(plano.map((consulta) => executar(consulta, api)));

  // Filmes com qualquer reação já foram vistos: não voltam como recomendação.
  const bloqueados = new Set([...(entrada.excluir ?? []), ...reacoes.map((r) => r.tmdbId)]);
  const usados = new Set<number>();
  const contexto = { favoritos: preferencias.generos, bonus: bonusPorGenero(reacoes), gerador };

  function escolher(filmes: FilmeResumo[]): Recomendacao[] {
    const livres = semRepetidos(filmes).filter((f) => !bloqueados.has(f.id) && !usados.has(f.id));
    const escolhidos = pontuar(livres, contexto)
      .slice(0, MAX_POR_SECAO)
      .map((filme) => ({
        ...filme,
        motivo: motivoPorGeneros(filme.generos, preferencias.generos),
      }));
    for (const filme of escolhidos) usados.add(filme.id);
    return escolhidos;
  }

  const secoes: Secao[] = [];

  const paraVoce = resultados.filter((r) => r.consulta.tipo === "para-voce");
  const filmesParaVoce = paraVoce.flatMap((r) => r.filmes ?? []);
  if (paraVoce.every((r) => r.filmes === null)) {
    secoes.push({ id: "para-voce", titulo: "Escolhidos para você", filmes: [], erro: true });
  } else {
    secoes.push({
      id: "para-voce",
      titulo: "Escolhidos para você",
      filmes: escolher(filmesParaVoce),
    });
  }

  const listasParecidos = resultados.flatMap((r) =>
    r.consulta.tipo === "parecidos" && r.filmes
      ? [{ origem: r.consulta.origem, filmes: r.filmes }]
      : [],
  );
  const jaUsados = new Set([...bloqueados, ...usados]);
  for (const { origem, filmes } of agregarParecidos(listasParecidos, jaUsados)) {
    const recomendacoes = filmes.map(({ peso, ...filme }) => ({
      ...filme,
      motivo: motivoParecido(origem),
      pontuacao: peso,
    }));
    for (const filme of recomendacoes) usados.add(filme.id);
    secoes.push({
      id: `parecidos-${origem.tmdbId}`,
      titulo: tituloParecidos(origem),
      filmes: recomendacoes,
    });
  }

  for (const resultado of resultados) {
    if (resultado.consulta.tipo !== "genero") continue;
    const { generoId } = resultado.consulta;
    const nome = GENEROS.find((genero) => genero.id === generoId)?.nome ?? "Filmes";
    const base = { id: `genero-${generoId}`, titulo: `${nome} para você` };
    if (resultado.filmes === null) {
      secoes.push({ ...base, filmes: [], erro: true });
      continue;
    }
    secoes.push({ ...base, filmes: escolher(resultado.filmes) });
  }

  return secoes.filter((secao) => secao.erro || secao.filmes.length > 0);
}
import { GENEROS } from "@/features/preferencias/generos";
import { filtrosDeDuracao, PERFIS } from "@/features/recomendacao/perfil";
import { sortearInteiro } from "@/features/recomendacao/semente";
import type { ReacaoMotor, EntradaMotor, Gerador } from "@/features/recomendacao/tipos";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export type Consulta =
  | { tipo: "para-voce"; filtros: FiltrosDescoberta }
  | { tipo: "parecidos"; origem: ReacaoMotor }
  | { tipo: "genero"; generoId: number; filtros: FiltrosDescoberta };

const MAX_ORIGENS_PARECIDOS = 3;

const PRIORIDADE = { amei: 0, gostei: 1 } as const;

/** Reações "Amei" e "Gostei" que viram fonte de parecidos: "Amei" primeiro, até 3. */
export function origensDeParecidos(reacoes: ReacaoMotor[] = []): ReacaoMotor[] {
  return reacoes
    .filter(
      (r): r is ReacaoMotor & { reacao: keyof typeof PRIORIDADE } => r.reacao !== "nao-gostei",
    )
    .sort((a, b) => PRIORIDADE[a.reacao] - PRIORIDADE[b.reacao])
    .slice(0, MAX_ORIGENS_PARECIDOS);
}

export function planejar({ preferencias, reacoes }: EntradaMotor, gerador: Gerador): Consulta[] {
  const perfil = PERFIS[preferencias.frequencia];
  const base: FiltrosDescoberta = {
    ...filtrosDeDuracao(preferencias.duracao),
    votosMin: perfil.votosMin,
    notaMin: perfil.notaMin,
    ordem: "popularidade",
  };

  const primeira = sortearInteiro(gerador, 1, perfil.paginaMax);
  let segunda = sortearInteiro(gerador, 1, perfil.paginaMax - 1);
  if (segunda >= primeira) segunda += 1;

  const paraVoce: Consulta[] =
    perfil.paginaMax > 1
      ? [primeira, segunda].map((pagina) => ({
          tipo: "para-voce",
          filtros: { ...base, generos: preferencias.generos, pagina },
        }))
      : (["popularidade", "nota"] as const).map((ordem) => ({
          tipo: "para-voce",
          filtros: { ...base, generos: preferencias.generos, ordem, pagina: 1 },
        }));

  const parecidos: Consulta[] = origensDeParecidos(reacoes).map((origem) => ({
    tipo: "parecidos",
    origem,
  }));

  const porGenero: Consulta[] = GENEROS.filter(({ id }) => preferencias.generos.includes(id)).map(
    ({ id }) => ({
      tipo: "genero",
      generoId: id,
      filtros: { ...base, generos: [id], pagina: sortearInteiro(gerador, 1, perfil.paginaMax) },
    }),
  );

  return [...paraVoce, ...parecidos, ...porGenero];
}
import type { Duracao, Frequencia } from "@/features/preferencias/opcoes";
import type { FiltrosDescoberta } from "@/lib/tmdb/tipos";

export function filtrosDeDuracao(
  duracao: Duracao,
): Pick<FiltrosDescoberta, "duracaoMin" | "duracaoMax"> {
  switch (duracao) {
    case "curta":
      return { duracaoMax: 90 };
    case "media":
      return { duracaoMin: 90, duracaoMax: 120 };
    case "longa":
      return { duracaoMin: 120 };
    case "indiferente":
      return {};
  }
}

/**
 * Quanto mais a pessoa assiste, menos óbvios os filmes: menos votos e nota mínimos
 * e páginas mais fundas do TMDB. Quem assiste pouco recebe os consagrados.
 */
export const PERFIS: Record<Frequencia, { votosMin: number; notaMin: number; paginaMax: number }> =
  {
    raramente: { votosMin: 2000, notaMin: 7, paginaMax: 2 },
    mensal: { votosMin: 1000, notaMin: 6.5, paginaMax: 3 },
    semanal: { votosMin: 300, notaMin: 6.5, paginaMax: 5 },
    diaria: { votosMin: 100, notaMin: 6, paginaMax: 10 },
  };
import "server-only";

import type { z } from "zod";

import { clienteTmdbPadrao, TmdbErro, type ClienteTmdb, type Parametros } from "@/lib/tmdb/cliente";
import {
  detalhesTmdb,
  filmeTmdb,
  paginaTmdb,
  type DetalhesTmdb,
  type FilmeTmdb,
} from "@/lib/tmdb/esquemas";
import type {
  FilmeDetalhes,
  FilmeResumo,
  FiltrosDescoberta,
  OrdemDescoberta,
  Pagina,
  Provedor,
} from "@/lib/tmdb/tipos";

const HORA = 3600;
const CACHE_LISTAS = 6 * HORA;
const CACHE_FILME = 24 * HORA;
const MAX_ELENCO = 10;
const MAX_PAGINA = 500;

const ORDENS: Record<OrdemDescoberta, string> = {
  popularidade: "popularity.desc",
  nota: "vote_average.desc",
  lancamento: "primary_release_date.desc",
};

const PAGINA_VAZIA: Pagina<never> = { itens: [], pagina: 1, totalPaginas: 0, totalResultados: 0 };

function validar<T extends z.ZodType>(esquema: T, dados: unknown): z.infer<T> {
  const resultado = esquema.safeParse(dados);
  if (!resultado.success) throw new TmdbErro("Resposta inesperada do TMDB", null);
  return resultado.data;
}

function limitarPagina(pagina = 1) {
  return Math.min(Math.max(Math.trunc(pagina), 1), MAX_PAGINA);
}

function anoDe(data: string | null): number | null {
  const ano = Number(data?.slice(0, 4));
  return ano > 0 ? ano : null;
}

function paraResumo(filme: FilmeTmdb): FilmeResumo {
  return {
    id: filme.id,
    titulo: filme.title,
    tituloOriginal: filme.original_title,
    sinopse: filme.overview,
    posterPath: filme.poster_path,
    backdropPath: filme.backdrop_path,
    generos: filme.genre_ids,
    ano: anoDe(filme.release_date),
    nota: filme.vote_average,
    votos: filme.vote_count,
    popularidade: filme.popularity,
  };
}

function paraPagina(dados: unknown): Pagina<FilmeResumo> {
  const pagina = validar(paginaTmdb(filmeTmdb), dados);
  return {
    itens: pagina.results.map(paraResumo),
    pagina: pagina.page,
    totalPaginas: pagina.total_pages,
    totalResultados: pagina.total_results,
  };
}

function trailerDe(videos: DetalhesTmdb["videos"]["results"]): string | null {
  const trailers = videos.filter((video) => video.site === "YouTube" && video.type === "Trailer");
  return (trailers.find((video) => video.official) ?? trailers[0])?.key ?? null;
}

function paraProvedores(
  lista: { provider_id: number; provider_name: string; logo_path: string | null }[],
): Provedor[] {
  return lista.map((p) => ({ id: p.provider_id, nome: p.provider_name, logoPath: p.logo_path }));
}

function paraDetalhes(filme: DetalhesTmdb): FilmeDetalhes {
  const brasil = filme["watch/providers"].results.BR;
  return {
    ...paraResumo({ ...filme, genre_ids: [] }),
    generos: filme.genres.map(({ id, name }) => ({ id, nome: name })),
    duracaoMin: filme.runtime || null,
    slogan: filme.tagline,
    trailerYoutube: trailerDe(filme.videos.results),
    elenco: filme.credits.cast.slice(0, MAX_ELENCO).map((pessoa) => ({
      nome: pessoa.name,
      personagem: pessoa.character,
      fotoPath: pessoa.profile_path,
    })),
    direcao: filme.credits.crew.filter((p) => p.job === "Director").map((p) => p.name),
    ondeAssistir: brasil
      ? {
          link: brasil.link,
          assinatura: paraProvedores(brasil.flatrate),
          aluguel: paraProvedores(brasil.rent),
          compra: paraProvedores(brasil.buy),
        }
      : null,
    parecidos: (filme.recommendations?.results ?? []).map(paraResumo),
  };
}

/** Funções de filmes sobre um cliente qualquer; os testes passam um cliente com `fetch` falso. */
export function criarApiFilmes(cliente: ClienteTmdb) {
  return {
    async descobrirFilmes(filtros: FiltrosDescoberta = {}): Promise<Pagina<FilmeResumo>> {
      const parametros: Parametros = {
        with_genres: filtros.generos?.length ? filtros.generos.join("|") : undefined,
        without_genres: filtros.semGeneros?.length ? filtros.semGeneros.join(",") : undefined,
        "with_runtime.gte": filtros.duracaoMin,
        "with_runtime.lte": filtros.duracaoMax,
        "vote_average.gte": filtros.notaMin,
        "vote_count.gte": filtros.votosMin,
        primary_release_year: filtros.ano,
        sort_by: ORDENS[filtros.ordem ?? "popularidade"],
        page: limitarPagina(filtros.pagina),
        region: "BR",
        include_adult: false,
      };
      return paraPagina(await cliente.requisitar("/discover/movie", parametros, CACHE_LISTAS));
    },

    async obterFilme(id: number): Promise<FilmeDetalhes | null> {
      try {
        const dados = await cliente.requisitar(
          `/movie/${id}`,
          { append_to_response: "videos,credits,watch/providers,recommendations" },
          CACHE_FILME,
        );
        return paraDetalhes(validar(detalhesTmdb, dados));
      } catch (erro) {
        if (erro instanceof TmdbErro && erro.status === 404) return null;
        throw erro;
      }
    },

    async recomendacoesDe(id: number, pagina = 1): Promise<Pagina<FilmeResumo>> {
      const dados = await cliente.requisitar(
        `/movie/${id}/recommendations`,
        { page: limitarPagina(pagina) },
        CACHE_FILME,
      );
      return paraPagina(dados);
    },

    async buscarFilmes(texto: string, pagina = 1): Promise<Pagina<FilmeResumo>> {
      const consulta = texto.trim();
      if (!consulta) return PAGINA_VAZIA;
      const dados = await cliente.requisitar(
        "/search/movie",
        { query: consulta, page: limitarPagina(pagina), region: "BR", include_adult: false },
        CACHE_LISTAS,
      );
      return paraPagina(dados);
    },
  };
}

export type ApiFilmes = ReturnType<typeof criarApiFilmes>;

let padrao: ApiFilmes | undefined;
const api = () => (padrao ??= criarApiFilmes(clienteTmdbPadrao()));

export const descobrirFilmes: ApiFilmes["descobrirFilmes"] = (...args) =>
  api().descobrirFilmes(...args);
export const obterFilme: ApiFilmes["obterFilme"] = (...args) => api().obterFilme(...args);
export const recomendacoesDe: ApiFilmes["recomendacoesDe"] = (...args) =>
  api().recomendacoesDe(...args);
export const buscarFilmes: ApiFilmes["buscarFilmes"] = (...args) => api().buscarFilmes(...args);

