-- Preferências do onboarding. Ter uma linha aqui significa onboarding concluído.

create type public.duracao_preferida as enum ('curta', 'media', 'longa', 'indiferente');
create type public.frequencia_assistir as enum ('raramente', 'mensal', 'semanal', 'diaria');

create table public.preferencias (
  usuario_id uuid primary key references auth.users (id) on delete cascade,
  generos int[] not null
    check (cardinality(generos) between 1 and 5)
    -- Os 19 gêneros de filme do TMDB (src/features/preferencias/generos.ts).
    check (generos <@ array[
      28, 16, 12, 10770, 35, 80, 99, 18, 10751, 14, 37, 878, 10752, 36, 9648, 10402, 10749, 27, 53
    ]),
  duracao public.duracao_preferida not null,
  frequencia public.frequencia_assistir not null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

comment on table public.preferencias is 'Gostos informados no onboarding; uma linha por usuário.';

alter table public.preferencias enable row level security;

create policy "preferencias: dono lê as próprias"
  on public.preferencias for select
  to authenticated
  using (usuario_id = (select auth.uid()));

create policy "preferencias: dono cria as próprias"
  on public.preferencias for insert
  to authenticated
  with check (usuario_id = (select auth.uid()));

create policy "preferencias: dono atualiza as próprias"
  on public.preferencias for update
  to authenticated
  using (usuario_id = (select auth.uid()))
  with check (usuario_id = (select auth.uid()));

create trigger preferencias_atualizado_em
  before update on public.preferencias
  for each row execute function public.tocar_atualizado_em();
-- Reações aos filmes ("Não é pra mim", "Gostei", "Amei"): sinal de gosto para o motor.
-- Título e gêneros são copiados do TMDB no momento da reação, para o motor não precisar
-- consultar a API por filme.

create type public.reacao_filme as enum ('nao-gostei', 'gostei', 'amei');

create table public.reacoes (
  usuario_id uuid not null references auth.users (id) on delete cascade,
  tmdb_id int not null check (tmdb_id > 0),
  reacao public.reacao_filme not null,
  titulo text not null check (char_length(titulo) between 1 and 300),
  generos int[] not null default '{}',
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now(),
  primary key (usuario_id, tmdb_id)
);

comment on table public.reacoes is 'Reação de cada usuário a cada filme; uma por par usuário/filme.';

alter table public.reacoes enable row level security;

create policy "reacoes: dono lê as próprias"
  on public.reacoes for select
  to authenticated
  using (usuario_id = (select auth.uid()));

create policy "reacoes: dono cria as próprias"
  on public.reacoes for insert
  to authenticated
  with check (usuario_id = (select auth.uid()));

create policy "reacoes: dono atualiza as próprias"
  on public.reacoes for update
  to authenticated
  using (usuario_id = (select auth.uid()))
  with check (usuario_id = (select auth.uid()));

create policy "reacoes: dono apaga as próprias"
  on public.reacoes for delete
  to authenticated
  using (usuario_id = (select auth.uid()));

create trigger reacoes_atualizado_em
  before update on public.reacoes
  for each row execute function public.tocar_atualizado_em();
import { z } from "zod";

import { IDS_GENEROS, MAX_GENEROS } from "@/features/preferencias/generos";
import { DURACOES, FREQUENCIAS } from "@/features/preferencias/opcoes";

export const MENSAGENS = {
  generos: "Escolha de 1 a 5 gêneros.",
  duracao: "Escolha uma duração.",
  frequencia: "Escolha uma frequência.",
} as const;

export const generosSchema = z
  .array(z.number({ error: MENSAGENS.generos }).int({ error: MENSAGENS.generos }), {
    error: MENSAGENS.generos,
  })
  .min(1, { error: MENSAGENS.generos })
  .max(MAX_GENEROS, { error: MENSAGENS.generos })
  .refine((ids) => ids.every((id) => IDS_GENEROS.has(id)), { error: MENSAGENS.generos })
  .refine((ids) => new Set(ids).size === ids.length, { error: MENSAGENS.generos });

export const preferenciasSchema = z.object({
