  amei: 0.1,
  gostei: 0.05,
  "nao-gostei": -0.1,
};

const DESEMPATE_MAX = 0.02;

/** Soma, por gênero, o peso das reações dadas a filmes daquele gênero. */
export function bonusPorGenero(reacoes: ReacaoMotor[] = []): Map<number, number> {
  const bonus = new Map<number, number>();
