import { describe, expect, it } from "vitest";

import { GENEROS } from "@/features/preferencias/generos";
import { MENSAGENS, preferenciasSchema } from "@/features/preferencias/schema";

const valido = { generos: [28, 18], duracao: "media", frequencia: "semanal" };

function erroDe(dados: Record<string, unknown>) {
  const resultado = preferenciasSchema.safeParse(dados);
  return resultado.success ? undefined : resultado.error.issues[0]?.message;
}

describe("GENEROS", () => {
  it("tem os 19 gêneros do TMDB com IDs únicos", () => {
    expect(GENEROS).toHaveLength(19);
    expect(new Set(GENEROS.map((genero) => genero.id)).size).toBe(19);
  });

  it("está em ordem alfabética de nome", () => {
    const nomes = GENEROS.map((genero) => genero.nome);
    expect(nomes).toEqual([...nomes].sort((a, b) => a.localeCompare(b, "pt-BR")));
  });
});

describe("preferenciasSchema", () => {
  it("aceita 1 gênero", () => {
    expect(preferenciasSchema.safeParse({ ...valido, generos: [28] }).success).toBe(true);
  });

  it("aceita 5 gêneros", () => {
    expect(preferenciasSchema.safeParse({ ...valido, generos: [28, 18, 35, 27, 53] }).success).toBe(
      true,
    );
  });

  it.each([
    ["nenhum gênero", []],
    ["6 gêneros", [28, 18, 35, 27, 53, 99]],
    ["ID fora da lista", [28, 1]],
    ["gênero repetido", [28, 28]],
  ])("rejeita %s", (_caso, generos) => {
    expect(erroDe({ ...valido, generos })).toBe(MENSAGENS.generos);
  });

  it("rejeita duração inválida", () => {
    expect(erroDe({ ...valido, duracao: "enorme" })).toBe(MENSAGENS.duracao);
  });

  it("rejeita frequência inválida", () => {
    expect(erroDe({ ...valido, frequencia: "anual" })).toBe(MENSAGENS.frequencia);
  });
});
import { beforeAll, describe, expect, it } from "vitest";

import { criarUsuario } from "../../support/supabase-local";

describe("RLS de preferencias", () => {
  let a: Awaited<ReturnType<typeof criarUsuario>>;
  let b: Awaited<ReturnType<typeof criarUsuario>>;

  beforeAll(async () => {
    a = await criarUsuario("Usuária A");
    b = await criarUsuario("Usuário B");
    const { error } = await b.cliente
      .from("preferencias")
      .upsert({ usuario_id: b.id, generos: [27], duracao: "curta", frequencia: "mensal" });
    if (error) throw error;
  });

  it("o usuário grava e lê as próprias preferências, e o upsert atualiza a mesma linha", async () => {
    const primeira = await a.cliente
      .from("preferencias")
      .upsert({ usuario_id: a.id, generos: [28, 18], duracao: "media", frequencia: "semanal" });
    expect(primeira.error).toBeNull();

    const segunda = await a.cliente
      .from("preferencias")
      .upsert({ usuario_id: a.id, generos: [35], duracao: "longa", frequencia: "diaria" });
    expect(segunda.error).toBeNull();

    const { data } = await a.cliente
      .from("preferencias")
      .select("usuario_id, generos, duracao, frequencia");
    expect(data).toEqual([
      { usuario_id: a.id, generos: [35], duracao: "longa", frequencia: "diaria" },
    ]);
  });

  it("o usuário recebe zero linhas ao ler as preferências de outro", async () => {
    const { data, error } = await a.cliente
      .from("preferencias")
      .select("usuario_id")
      .eq("usuario_id", b.id);
    expect(error).toBeNull();
    expect(data).toEqual([]);
  });

  it("o update de um usuário nas preferências de outro não altera nada", async () => {
    const { data } = await a.cliente
      .from("preferencias")
      .update({ generos: [99] })
      .eq("usuario_id", b.id)
      .select();
    expect(data).toEqual([]);

    const { data: deB } = await b.cliente.from("preferencias").select("generos").single();
    expect(deB?.generos).toEqual([27]);
  });

  it("o usuário não consegue inserir preferências em nome de outro", async () => {
    const outro = await criarUsuario("Usuário C");
    const { error } = await a.cliente
      .from("preferencias")
      .insert({ usuario_id: outro.id, generos: [28], duracao: "curta", frequencia: "mensal" });
    expect(error?.code).toBe("42501");
  });

  it.each([
    ["vazio", []],
    ["com 6 itens", [28, 18, 35, 27, 53, 99]],
    ["com ID fora da lista", [28, 1]],
  ])("o banco recusa generos %s", async (_caso, generos) => {
    const { cliente, id } = await criarUsuario();
    const { error } = await cliente
      .from("preferencias")
      .insert({ usuario_id: id, generos, duracao: "media", frequencia: "semanal" });
    expect(error?.code).toBe("23514");
  });
});
