import { GENEROS } from "@/features/preferencias/generos";
import { VERBO_REACAO } from "@/features/reacoes/opcoes";
import type { ReacaoMotor } from "@/features/recomendacao/tipos";

const MAX_GENEROS_NO_MOTIVO = 3;

function listar(nomes: string[]): string {
  if (nomes.length <= 1) return nomes.join("");
  return `${nomes.slice(0, -1).join(", ")} e ${nomes.at(-1)}`;
}

/** "Porque você curte Drama e Thriller", com no máximo 3 gêneros, na ordem de GENEROS. */
export function motivoPorGeneros(generosDoFilme: number[], favoritos: number[]): string {
  const emComum = GENEROS.filter(
    ({ id }) => generosDoFilme.includes(id) && favoritos.includes(id),
  ).map(({ nome }) => nome);
  if (emComum.length === 0) return "Popular entre quem tem gostos parecidos";
  return `Porque você curte ${listar(emComum.slice(0, MAX_GENEROS_NO_MOTIVO))}`;
}

/** "Parecido com X, que você amou". */
export function motivoParecido(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `Parecido com ${origem.titulo}, ${verbo.motivo}` : `Parecido com ${origem.titulo}`;
}

/** "Porque você amou X" / "Porque você gostou de X". */
export function tituloParecidos(origem: ReacaoMotor): string {
  const verbo = origem.reacao === "nao-gostei" ? null : VERBO_REACAO[origem.reacao];
  return verbo ? `${verbo.titulo} ${origem.titulo}` : `Parecidos com ${origem.titulo}`;
}
import type { ReacaoMotor } from "@/features/recomendacao/tipos";
import type { FilmeResumo } from "@/lib/tmdb/tipos";

const PESO_ORIGEM: Partial<Record<ReacaoMotor["reacao"], number>> = { amei: 1, gostei: 0.6 };
const MAX_POR_SECAO = 20;

export type ListaDeParecidos = { origem: ReacaoMotor; filmes: FilmeResumo[] };
export type SecaoParecidos = {
  origem: ReacaoMotor;
  filmes: (FilmeResumo & { peso: number })[];
};

/**
 * Junta as recomendações do TMDB de cada filme marcado com "Amei" ou "Gostei". Cada candidato soma
 * `peso da origem × (1 − posição / tamanho da lista)` em todas as listas em que aparece,
 * e fica na seção da origem que mais contribuiu para ele.
 */
export function agregarParecidos(
  listas: ListaDeParecidos[],
  excluir: ReadonlySet<number>,
): SecaoParecidos[] {
  const comReacao = new Set(listas.map(({ origem }) => origem.tmdbId));
  const candidatos = new Map<
    number,
    { filme: FilmeResumo; peso: number; melhorOrigem: ReacaoMotor; melhorContribuicao: number }
  >();

  for (const { origem, filmes } of listas) {
    const pesoOrigem = PESO_ORIGEM[origem.reacao] ?? 0;
    filmes.forEach((filme, posicao) => {
      if (excluir.has(filme.id) || comReacao.has(filme.id)) return;
      const contribuicao = pesoOrigem * (1 - posicao / filmes.length);
      const atual = candidatos.get(filme.id);
      if (!atual) {
        candidatos.set(filme.id, {
          filme,
          peso: contribuicao,
          melhorOrigem: origem,
          melhorContribuicao: contribuicao,
        });
        return;
      }
      atual.peso += contribuicao;
      if (contribuicao > atual.melhorContribuicao) {
        atual.melhorOrigem = origem;
        atual.melhorContribuicao = contribuicao;
      }
    });
  }

  const ordenados = [...candidatos.values()].sort((a, b) => b.peso - a.peso);
  const secoes = new Map<number, SecaoParecidos>();
  for (const { filme, peso, melhorOrigem } of ordenados) {
    const secao = secoes.get(melhorOrigem.tmdbId) ?? { origem: melhorOrigem, filmes: [] };
    if (secao.filmes.length < MAX_POR_SECAO) secao.filmes.push({ ...filme, peso });
    secoes.set(melhorOrigem.tmdbId, secao);
  }
  // A ordem de inserção já segue o candidato mais bem colocado de cada origem.
  return [...secoes.values()];
}

