    tituloOriginal: `Film ${id}`,
    sinopse: "",
    posterPath: null,
    backdropPath: null,
    generos: [18],
    ano: 2020,
    nota: 7,
    votos: 1000,
    popularidade: 50,
    ...sobrescrever,
  };
}

/** Gerador "aleatório" fixo, para testes que não dependem do sorteio. */
