import { cn } from "cn";

import { GENEROS, MAX_GENEROS } from "@/features/preferencias/generos";

type Props = {
  titulo: string;
  selecionados: number[];
  aoAlternar: (id: number) => void;
};

/** Os 19 gêneros como botões de alternância, com limite de 5. Usado no onboarding e no perfil. */
export function ChipsGeneros({ titulo, selecionados, aoAlternar }: Props) {
  const limiteAtingido = selecionados.length >= MAX_GENEROS;

  return (
    <div className="flex flex-col gap-3">
      <h2 className="text-lg font-semibold">{titulo}</h2>
      <p className="text-muted-foreground text-sm">
        {limiteAtingido
          ? "Você pode escolher até 5 gêneros."
          : "Escolha de 1 a 5. Eles guiam suas recomendações."}
      </p>
      <div className="flex flex-wrap gap-2">
        {GENEROS.map(({ id, nome }) => {
          const marcado = selecionados.includes(id);
          return (
            <button
              key={id}
              type="button"
              aria-pressed={marcado}
              disabled={!marcado && limiteAtingido}
              onClick={() => aoAlternar(id)}
              className={cn(
                "border-border rounded-full border px-4 py-2 text-sm transition-colors outline-none",
                "hover:bg-muted focus-visible:ring-ring/50 focus-visible:ring-3",
                "disabled:cursor-not-allowed disabled:opacity-40",
                marcado && "border-primary bg-primary text-primary-foreground hover:bg-primary/80",
              )}
            >
              {nome}
            </button>
          );
        })}
      </div>
    </div>
  );
}

/** Liga/desliga um gênero numa lista. */
export function alternar(lista: number[], id: number): number[] {
  return lista.includes(id) ? lista.filter((atual) => atual !== id) : [...lista, id];
}
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";

import { OnboardingWizard } from "@/features/preferencias/components/onboarding-wizard";

vi.mock("@/features/preferencias/actions", () => ({ salvarPreferencias: vi.fn() }));

function genero(nome: string) {
  return screen.getByRole("button", { name: nome });
}

describe("OnboardingWizard", () => {
  it("só libera o Próximo depois de escolher um gênero", async () => {
    const usuario = userEvent.setup();
    render(<OnboardingWizard />);

    const proximo = screen.getByRole("button", { name: "Próximo" });
    expect(proximo).toBeDisabled();
    expect(screen.queryByRole("button", { name: "Voltar" })).not.toBeInTheDocument();

    await usuario.click(genero("Drama"));
    expect(genero("Drama")).toHaveAttribute("aria-pressed", "true");
    expect(proximo).toBeEnabled();
  });

  it("trava os outros gêneros ao chegar em 5 e avisa o limite", async () => {
    const usuario = userEvent.setup();
    render(<OnboardingWizard />);

    for (const nome of ["Ação", "Drama", "Comédia", "Terror", "Thriller"]) {
      await usuario.click(genero(nome));
    }

    expect(genero("Romance")).toBeDisabled();
    expect(genero("Ação")).toBeEnabled();
    expect(screen.getByText("Você pode escolher até 5 gêneros.")).toBeInTheDocument();

    await usuario.click(genero("Ação"));
    expect(genero("Romance")).toBeEnabled();
  });

  it("Voltar mantém os gêneros escolhidos", async () => {
    const usuario = userEvent.setup();
    render(<OnboardingWizard />);

    await usuario.click(genero("Ação"));
    await usuario.click(genero("Drama"));
    await usuario.click(screen.getByRole("button", { name: "Próximo" }));

    expect(screen.getByText("Passo 2 de 3")).toBeInTheDocument();
    expect(screen.getByRole("radiogroup", { name: "Duração preferida" })).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Próximo" })).toBeDisabled();

    await usuario.click(screen.getByRole("button", { name: "Voltar" }));
    expect(screen.getByText("Passo 1 de 3")).toBeInTheDocument();
    expect(genero("Ação")).toHaveAttribute("aria-pressed", "true");
    expect(genero("Drama")).toHaveAttribute("aria-pressed", "true");
  });

  it("chega ao passo 3 com o botão Concluir", async () => {
    const usuario = userEvent.setup();
    render(<OnboardingWizard />);

    await usuario.click(genero("Ação"));
    await usuario.click(screen.getByRole("button", { name: "Próximo" }));
    await usuario.click(screen.getByRole("radio", { name: "Tanto faz" }));
    await usuario.click(screen.getByRole("button", { name: "Próximo" }));

    expect(screen.getByText("Passo 3 de 3")).toBeInTheDocument();
    const concluir = screen.getByRole("button", { name: "Concluir" });
    expect(concluir).toBeDisabled();
    await usuario.click(screen.getByRole("radio", { name: "Toda semana" }));
    expect(concluir).toBeEnabled();
  });
});
export type TamanhoImagem = "w92" | "w185" | "w342" | "w500" | "w780" | "w1280" | "original";

/** URL do CDN de imagens do TMDB. Pode ser usado no servidor e no navegador. */
export function urlImagem(path: string | null, tamanho: TamanhoImagem): string | null {
  return path ? `https://image.tmdb.org/t/p/${tamanho}${path}` : null;
}
import type { Metadata } from "next";
import { redirect } from "next/navigation";

import { exigirUsuario } from "@/features/auth/sessao";
import { OnboardingWizard } from "@/features/preferencias/components/onboarding-wizard";
import { obterPreferencias } from "@/features/preferencias/consultas";

export const metadata: Metadata = { title: "Suas preferências" };

export default async function OnboardingPage() {
  const usuario = await exigirUsuario();
  if (await obterPreferencias()) redirect("/dashboard");

