  vi.mocked(sugerirFilmesOnboarding).mockReset().mockImplementation(async (filtros) => ({
    filmes: (filtros.generos ? ids(1, 20) : [...ids(1, 5), ...ids(101, 115)]).map(opcao),
  }));
  vi.mocked(buscarFilmesOnboarding)
    .mockReset()
    .mockImplementation(async () => ({ filmes: [opcao(500)] }));
});

