  await usuario.click(screen.getByRole("radio", { name: "Toda semana" }));
  if (passo === 4) return usuario;
  await usuario.click(avancar());
  if (passo === 5) return usuario;
  await usuario.click(avancar());
  await screen.findByRole("button", { name: "Marcar Filme 1" });
