import { expect, type Page } from "@playwright/test";

import { SENHA_TESTE } from "../support/supabase-local";

export async function cadastrar(page: Page, nome: string, email: string) {
  await page.goto("/cadastro");
  await page.getByLabel("Nome").fill(nome);
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Senha", { exact: true }).fill(SENHA_TESTE);
  await page.getByLabel("Confirme a senha").fill(SENHA_TESTE);
  await page.getByRole("main").getByRole("button", { name: "Criar conta" }).click();
}

export async function entrar(page: Page, email: string, senha = SENHA_TESTE) {
  await page.getByLabel("Email").fill(email);
  await page.getByLabel("Senha").fill(senha);
  await page.getByRole("main").getByRole("button", { name: "Entrar" }).click();
}

export async function sair(page: Page) {
  await page.getByRole("banner").getByRole("button", { name: "Sair" }).click();
  await expect(page).toHaveURL("/");
}

/** Conclui o wizard com Ação + Drama, filmes médios, toda semana. */
export async function concluirOnboarding(page: Page) {
  await expect(page).toHaveURL("/onboarding");
  const main = page.getByRole("main");
  await main.getByRole("button", { name: "Ação", exact: true }).click();
  await main.getByRole("button", { name: "Drama", exact: true }).click();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Médios (90 a 120 min)" }).check();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Toda semana" }).check();
  await main.getByRole("button", { name: "Concluir" }).click();
  await expect(page).toHaveURL("/dashboard");
}

export const RESUMO_ONBOARDING = "Ação, Drama · Médios (90 a 120 min) · Toda semana";
import { expect, test } from "@playwright/test";

import { emailAleatorio } from "../support/supabase-local";
import { cadastrar, concluirOnboarding, RESUMO_ONBOARDING } from "./helpers";

test("cadastro, onboarding completo e resumo no dashboard", async ({ page }) => {
  await cadastrar(page, "Fê Rocha", emailAleatorio("e2e"));
  await concluirOnboarding(page);

  await expect(page.getByRole("heading", { level: 1 })).toHaveText("Olá, Fê Rocha");
  await expect(page.getByTestId("resumo-preferencias")).toHaveText(RESUMO_ONBOARDING);
});

test("sem preferências, o dashboard manda para o onboarding", async ({ page }) => {
  await cadastrar(page, "Gabi Nunes", emailAleatorio("e2e"));
  await expect(page).toHaveURL("/onboarding");

  await page.goto("/dashboard");
  await expect(page).toHaveURL("/onboarding");
});

test("depois de concluir, o onboarding manda para o dashboard", async ({ page }) => {
  await cadastrar(page, "Hugo Prado", emailAleatorio("e2e"));
  await concluirOnboarding(page);

  await page.goto("/onboarding");
  await expect(page).toHaveURL("/dashboard");
});

test("sem sessão, o onboarding exige login", async ({ page }) => {
  await page.goto("/onboarding");
  await expect(page).toHaveURL("/login?next=%2Fonboarding");
});
  await expect(page).toHaveURL("/dashboard?rodada=1");
  await expect(page.getByRole("region", { name: "Escolhidos para você" })).toBeVisible();

  expect(await idsDosFilmes(page)).not.toEqual(antes);
});

test("uma seção que falha mostra o erro e as outras carregam", async ({ page }) => {
  await cadastrar(page, "Kátia Moura", emailAleatorio("e2e"));
  await expect(page).toHaveURL("/onboarding");
  const main = page.getByRole("main");
  await main.getByRole("button", { name: "Documentário", exact: true }).click();
  await main.getByRole("button", { name: "Drama", exact: true }).click();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Tanto faz" }).check();
  await main.getByRole("button", { name: "Próximo" }).click();
  await main.getByRole("radio", { name: "Toda semana" }).check();
  await main.getByRole("button", { name: "Concluir" }).click();
  await expect(page).toHaveURL("/dashboard");

  const documentario = main.getByRole("region", { name: "Documentário para você" });
  await expect(documentario.getByText("Não foi possível carregar agora.")).toBeVisible();
  await expect(documentario.getByRole("link", { name: "Tentar de novo" })).toBeVisible();

  const drama = main.getByRole("region", { name: "Drama para você" });
  await expect(drama.getByRole("listitem").first()).toBeVisible();
});
import { expect, test } from "@playwright/test";

import { emailAleatorio } from "../support/supabase-local";
import { cadastrar, concluirOnboarding } from "./helpers";

test("trocar nome e preferências reflete no header e no dashboard", async ({ page }) => {
  await cadastrar(page, "Tiago Lima", emailAleatorio("e2e"));
  await concluirOnboarding(page);

  await page.getByRole("banner").getByRole("link", { name: "Tiago Lima" }).click();
  await expect(page).toHaveURL("/perfil");
  const main = page.getByRole("main");

  const dados = main.getByRole("region", { name: "Seus dados" });
  await dados.getByLabel("Nome").fill("Novo Nome");
  await dados.getByRole("button", { name: "Salvar nome" }).click();
  await expect(dados.getByRole("status")).toHaveText("Alterações salvas.");
  await expect(page.getByRole("banner").getByRole("link", { name: "Novo Nome" })).toBeVisible();

  const preferencias = main.getByRole("region", { name: "Suas preferências" });
  for (const genero of ["Ação", "Drama", "Terror"]) {
    await preferencias.getByRole("button", { name: genero, exact: true }).click();
  }
  await preferencias.getByRole("button", { name: "Salvar preferências" }).click();
  await expect(preferencias.getByRole("status")).toHaveText("Alterações salvas.");

  await page.goto("/dashboard");
  await expect(page.getByTestId("resumo-preferencias")).toHaveText(/^Terror · /);
  await expect(page.getByRole("region", { name: "Terror para você" })).toBeVisible();
  await expect(page.getByRole("region", { name: "Ação para você" })).toHaveCount(0);
});

test("sem sessão, /perfil exige login", async ({ page }) => {
  await page.goto("/perfil");
  await expect(page).toHaveURL("/login?next=%2Fperfil");
});
